'use strict';
const field=s=>document.querySelector(s);
const courseMapping={q:'#course-query',stage:'#course-stage',audience:'#course-audience',area:'#course-area',provider:'#course-provider',sort:'#course-sort'};
function courseState(){return Object.fromEntries(Object.entries(courseMapping).map(([k,s])=>[k,field(s).value]));}
function filteredCourses(){return LeadershipDiscovery.filter(COURSES,courseState());}
function renderCourses(){const s=courseState(),rows=filteredCourses();field('#course-count').textContent=`${rows.length} ${rows.length===1?'course':'courses'} found`;field('#course-audience-help').textContent=audienceHelp(s.audience);field('#course-rows').innerHTML=rows.map(r=>`<tr data-record="${escapeText(r.id)}"><th scope="row"><span class="audience-badge">${escapeText(r.audienceLabel)}</span><button class="course-detail" data-course="${escapeText(r.id)}">${escapeText(r.title)}</button><p>${escapeText(r.description)}</p><p class="course-eligibility"><strong>Who it’s for:</strong> ${escapeText(r.eligibility)}</p></th><td>${escapeText(r.area)}</td><td>${escapeText(r.id==='E005'?'Confirm with provider':r.duration==='Not published'?'See provider':r.duration)}</td><td>${escapeText(r.owner)}</td><td><a href="${escapeText(r.url)}" target="_blank" rel="noopener">View course &amp; registration</a><span class="access">Check current sessions</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty"><strong>No courses match this combination.</strong><p>Remove a filter or try a broader phrase.</p><button class="button" type="button" data-empty-reset>Clear all filters</button></td></tr>';renderFilterChips('#course-active',[{key:'stage',value:s.stage,label:s.stage},{key:'audience',value:s.audience!=='Employees',label:LeadershipDiscovery.labels[s.audience]},{key:'q',value:s.q,label:'Search: '+s.q},{key:'area',value:s.area,label:s.area},{key:'provider',value:s.provider,label:s.provider}],key=>{field(courseMapping[key]).value=key==='audience'?'Employees':'';renderCourses()});renderStageConnections(s.stage,s.audience);saveFilters(s);}
function resetCourses(){for(const[k,id]of Object.entries(courseMapping))field(id).value=k==='audience'?'Employees':k==='sort'?'title':'';renderCourses();}
document.querySelectorAll('.course-filters input,.course-filters select').forEach(e=>e.addEventListener(e.tagName==='INPUT'?'input':'change',renderCourses));field('#course-reset').addEventListener('click',resetCourses);field('#course-rows').addEventListener('click',e=>{const b=e.target.closest('[data-course]');if(b)showOpportunity(COURSES.find(r=>r.id===b.dataset.course));if(e.target.closest('[data-empty-reset]'))resetCourses()});restoreFilters(courseMapping);renderCourses();
